void loop() {
  int d = readDistance();
  if (d < 20) {
    stopMotors();
    turnRight();
    delay(300);
  } else {
    forwardMotors();
  }
}

int ldr = A0;
int led = 9;

void loop() {
  int light = analogRead(ldr);
  if (light < 300) {
    digitalWrite(led, HIGH);
  } else {
    digitalWrite(led, LOW);
  }
  delay(200);
}
